    // Select Photo A (active) and Photo B
    s.execute("library.select", &json!({"ids": [photo_a.0, photo_b.0], "active": photo_a.0})).unwrap();

    let initial_b_dev = (*s.develop_of(photo_b).unwrap()).clone();
